const lassoLoader = require("lasso-loader");
module.exports = {
    load: function () {
        return new Promise((resolve, reject) => {
            lassoLoader.async(function (err) {
                if (err) reject(err);
                else {
                    const {
                        autoUpdate,
                        flip,
                        computePosition,
                        shift,
                        offset,
                        arrow,
                        inline,
                    } = require("@floating-ui/dom");

                    resolve({
                        autoUpdate,
                        flip,
                        computePosition,
                        shift,
                        offset,
                        arrow,
                        inline,
                    });
                }
            });
        });
    },
};
